// Copies db/schema.sql and db/migrations/*.sql into lib/sql-bundle.js, so hosts that only ship
// the JavaScript a function imports (Vercel, Netlify…) can still run the migrations.
// Run after adding a migration: npm run bundle-sql
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const files = ['schema.sql', ...fs.readdirSync(path.join(root, 'db/migrations')).filter((f) => f.endsWith('.sql')).sort().map((f) => 'migrations/' + f)];
const out = `// Generated by scripts/bundle-sql.js from db/. Don't edit by hand: run \`npm run bundle-sql\`.\nexport default ${JSON.stringify(Object.fromEntries(files.map((f) => [f, fs.readFileSync(path.join(root, 'db', f), 'utf8').replace(/\r\n/g, '\n')])), null, 1)};\n`;
fs.writeFileSync(path.join(root, 'lib/sql-bundle.js'), out);
console.log(`lib/sql-bundle.js: ${files.length} files`);
